#nullable enable // autogenerated

using MVZ2.GameContent.Buffs.Projectiles;
using MVZ2.GameContent.Detections;
using MVZ2.GameContent.Entities;
using MVZ2.Vanilla.Contraptions;
using MVZ2.Vanilla.Detections;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Projectiles;
using MVZ2.Vanilla.Properties;
using PVZEngine.Buffs;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Models;
using PVZEngine.Tools;
using PVZEngine.Tools.Timing;
using UnityEngine;

namespace MVZ2.GameContent.Contraptions
{
    [AutoEntityBehaviourDefinition(VanillaContraptionNames.cattailMKII)]
    public class CattailMKII : AIEntityBehaviour
    {
        public CattailMKII(string nsp, string name) : base(nsp, name)
        {
        }
        protected override void UpdateAI(Entity entity)
        {
            base.UpdateAI(entity);
            UpdateState(entity);
        }

        public void UpdateState(Entity entity)
        {
            switch (entity.State)
            {
                case STATE_IDLE:
                default:
                    UpdateIdleState(entity);
                    break;
                case STATE_SHOOT_1:
                    UpdateShoot1State(entity);
                    break;
                case STATE_SHOOT_2:
                    UpdateShoot2State(entity);
                    break;
            }
        }
        public Entity? Shoot(Entity entity)
        {
            return entity.ShootProjectile()?.Let(p =>
            {
                p.AddBuff<HomingProjectileBuff>()?.Let(b =>
                {
                    HomingProjectileBuff.SetTarget(b, new EntityID(entity.Target));
                    HomingProjectileBuff.SetSpeed(b, entity.GetShotVelocity().magnitude);
                });
            });
        }
        private void StartIdleState(Entity entity)
        {
            entity.State = STATE_IDLE;
            var stateTimer = GetStateTimer(entity);
            if (stateTimer != null)
            {
                stateTimer.ResetTime(IDLE_STATE_FRAMES);
            }
        }
        private void StartShoot1State(Entity entity)
        {
            entity.State = STATE_SHOOT_1;
            entity.TriggerAnimation("Shoot");
            var stateTimer = GetStateTimer(entity);
            if (stateTimer != null)
            {
                stateTimer.ResetTime(SHOOT_1_STATE_FRAMES);
            }
        }
        private void StartShoot2State(Entity entity)
        {
            entity.State = STATE_SHOOT_2;
            var stateTimer = GetStateTimer(entity);
            if (stateTimer != null)
            {
                stateTimer.ResetTime(SHOOT_2_STATE_FRAMES);
            }
        }
        private void UpdateIdleState(Entity entity)
        {
            var stateTimer = GetOrCreateStateTimer(entity, IDLE_STATE_FRAMES);
            if (stateTimer.RunToExpired(entity.GetAttackSpeed()))
            {
                entity.Target = detector.DetectEntityWithTheLeast(entity, t => GetTargetPriority(entity, t));
                if (entity.Target != null)
                {
                    StartShoot1State(entity);
                }
                else
                {
                    stateTimer.Reset();
                }
            }
        }
        private void UpdateShoot1State(Entity entity)
        {
            var stateTimer = GetOrCreateStateTimer(entity, SHOOT_1_STATE_FRAMES);
            if (stateTimer.RunToExpired(entity.GetAttackSpeed()))
            {
                Shoot(entity);
                StartShoot2State(entity);
            }
        }
        private void UpdateShoot2State(Entity entity)
        {
            var stateTimer = GetOrCreateStateTimer(entity, SHOOT_2_STATE_FRAMES);
            if (stateTimer.RunToExpired(entity.GetAttackSpeed()))
            {
                Shoot(entity);
                StartIdleState(entity);
            }
        }
        private static FrameTimer GetOrCreateStateTimer(Entity entity, int frames)
        {
            var stateTimer = GetStateTimer(entity);
            if (stateTimer == null)
            {
                stateTimer = new FrameTimer(frames);
                SetStateTimer(entity, stateTimer);
            }
            return stateTimer;
        }
        private static float GetTargetPriority(Entity entity, Entity target)
        {
            float priority = 0;
            if (target.GetRelativeY() >= PRIOR_STRIKE_HEIGHT)
            {
                priority -= 10000;
            }
            var thisPosition = new Vector2(entity.Position.x, entity.Position.z);
            var targetPosition = new Vector2(target.Position.x, target.Position.z);
            priority += (targetPosition - thisPosition).magnitude;
            return priority;
        }
        public static FrameTimer? GetStateTimer(Entity entity) => entity.GetBehaviourField<FrameTimer>(PROP_STATE_TIMER);
        public static void SetStateTimer(Entity entity, FrameTimer timer) => entity.SetBehaviourField(PROP_STATE_TIMER, timer);
        protected Detector detector = new LawnDetector()
        {
            canDetectInvisible = false,
            factionTarget = FactionTarget.Hostile
        };
        public const int STATE_IDLE = VanillaContraptionStates.CATTAIL_IDLE;
        public const int STATE_SHOOT_1 = VanillaContraptionStates.CATTAIL_SHOOT_1;
        public const int STATE_SHOOT_2 = VanillaContraptionStates.CATTAIL_SHOOT_2;

        public const float PRIOR_STRIKE_HEIGHT = 40f;
        public const int ATTACK_INTERVAL = 45;
        public const int SHOOT_1_STATE_FRAMES = 10;
        public const int SHOOT_2_STATE_FRAMES = 12;
        public const int IDLE_STATE_FRAMES = ATTACK_INTERVAL - SHOOT_1_STATE_FRAMES - SHOOT_2_STATE_FRAMES;
        public static readonly VanillaEntityPropertyMeta<FrameTimer> PROP_STATE_TIMER = new VanillaEntityPropertyMeta<FrameTimer>("state_timer");
    }
}
